  if (!Number.isFinite(diameter) || diameter <= 0 || !Number.isFinite(hole) || hole <= 0 || hole > diameter || !Number.isFinite(holeClearance) || holeClearance < 0)
    return ends;
  const existingVias = (input.traces ?? []).flatMap(
    (t48) => t48.route.filter((p2) => p2.route_type === "via")
  );
  for (const end of [0, 1]) {
    const pad = connection.pointsToConnect[end];
    if ((pad.layers ?? [pad.layer]).includes(targetLayer2)) {
      const { layers: _layers, ...fixedPad } = pad;
      const point52 = { ...fixedPad, layer: targetLayer2 };
      ends[end].push({
        point: point52,
        length: 0,
        escape: {
          type: "pcb_trace",
          pcb_trace_id: `expanded_surface_${connection.name}_${end}`,
          connection_name: connection.name,
          source_trace_id: connection.source_trace_id ?? connection.name,
          route: [{ ...point52, route_type: "wire", width }]
        }
      });
      continue;
    }
    const owner = input.obstacles.find(
      (o2) => o2.componentId && distance15(o2.center, pad) < 1e-4
    );
    if (!owner) continue;
    const pitch = Math.min(
      ...input.obstacles.filter((o2) => o2.componentId === owner.componentId).map((o2) => distance15(o2.center, pad)).filter((d2) => d2 > 1e-4)
    );
    if (!Number.isFinite(pitch)) continue;
    const surfaceLimit = Math.min(2, 2.5 * pitch);
    const pitchSteps = Math.max(
      2,
      2 * Math.ceil(pitch / Math.max(0.01, input.minTraceWidth / 2) / 2)
    );
    const surfaceStep = Math.max(0.01, pitch / pitchSteps);
    const surfaceRadius = Math.ceil(surfaceLimit / surfaceStep) * surfaceStep;
    const candidates = [];
    for (let ix2 = -5; ix2 <= 5; ix2++)
      for (let iy2 = -5; iy2 <= 5; iy2++) {
        if (!ix2 && !iy2) continue;
        const point52 = {
          x: pad.x + ix2 * pitch / 2,
          y: pad.y + iy2 * pitch / 2,
          layer: targetLayer2
        };
        if (distance15(pad, point52) <= surfaceLimit + 1e-8) candidates.push(point52);
      }
    candidates.sort(
      (a2, b2) => distance15(pad, a2) - distance15(pad, b2) || a2.x - b2.x || a2.y - b2.y
    );
    const padToViaDistance = (owner.width + hole) / 2 + 1e-5;
    if (allowPadEdgeSites && owner.shape === "circle" && padToViaDistance <= surfaceLimit) {
      const diagonal = Math.SQRT1_2;
      for (const [x2, y2] of [
        [1, 0],
        [0, 1],
        [-1, 0],
        [0, -1],
        [diagonal, diagonal],
        [-diagonal, diagonal],
        [-diagonal, -diagonal],
        [diagonal, -diagonal]
      ])
        candidates.push({
          x: pad.x + x2 * padToViaDistance,
          y: pad.y + y2 * padToViaDistance,
          layer: targetLayer2
        });
    }
    // Only non-handoff pour layers form antipads around the barrel.
    // Surface/carrier routing and all physical copper retain their fixed list.
    const viaFixed = fixed.filter((copper) => !copper.isCopperPour || copper.layer === pad.layer || copper.layer === targetLayer2);
    const viaScenes = physical.map(
      (layer) => new VectorScene(
        input,
        {
          ...connection,
          pointsToConnect: [
            { ...pad, layer },
            { ...pad, layer }
          ]
        },
        diameter,
        viaFixed
      )
    );
    for (const alignSurfaceGrid of [false, true]) {
      if (alignSurfaceGrid && ends[end].length) break;
      const surfaceGrid = alignSurfaceGrid ? {
        step: surfaceStep,
        bounds: {
          minX: pad.x - surfaceRadius,
          maxX: pad.x + surfaceRadius,
          minY: pad.y - surfaceRadius,
          maxY: pad.y + surfaceRadius
        }
      } : {};
      for (const point52 of candidates) {
        if (viaScenes.some((scene2) => !scene2.visible(point52, point52))) continue;
        if (existingVias.some(
          (via) => distance15(via, point52) < hole / 2 + (via.via_hole_diameter ?? input.minViaHoleDiameter ?? 0.15) / 2 + holeClearance - 1e-8
        ))
          continue;
        const local = {
          ...connection,
          pointsToConnect: [pad, { ...point52, layer: pad.layer }]
        };
        const scene = new VectorScene(input, local, width, fixed);
        const search = new GridVisibilitySearch(
          scene,
          pad,
          point52,
          [],
          0,
          void 0,
          {
            ...surfaceGrid,
            checkReachability: true,
            allTerminalAttachments: true,
            maxLength: surfaceLimit,
            paretoLength: true
          }
        );
        try {
          let steps = 0;
          while (!search.solved && !search.failed && steps++ < 4e3) {
            search.step();
            yield;
          }
          if (!search.solved) continue;
          let top = reduceOrdinaryTurns(search.result, scene).map((p2) => ({
            ...p2,
            route_type: "wire",
            layer: pad.layer,
            width
          }));
          const topTrace = {
            type: "pcb_trace",
            pcb_trace_id: `expanded_surface_${connection.name}_${end}`,
            connection_name: connection.name,
            route: top
          };
          top = chamferOrdinaryCorners(
            { ...input, connections: [local] },
            [topTrace],
            fixed
          )[0].route;
          if (!scene.pathVisible(top) || length(top) > surfaceLimit + 1e-8 || !routeAnglesAreConventional([{ ...topTrace, route: top }]) || !tuningPathIsSelfClear(
            top,
            width + (input.minTraceToPadEdgeClearance ?? input.defaultObstacleMargin ?? 0.075)
          ))
            continue;
          const via = {
            x: point52.x,
            y: point52.y,
            route_type: "via",
            from_layer: pad.layer,
            to_layer: targetLayer2,
            layers: physical,
            via_diameter: diameter,
            via_hole_diameter: hole
          };
          ends[end].push({
            point: point52,
            length: length(top),
            escape: {
              type: "pcb_trace",
              pcb_trace_id: `expanded_dogbone_${connection.name}_${end}_${ends[end].length}`,
              connection_name: connection.name,
              source_trace_id: connection.source_trace_id ?? connection.name,
              route: [...top, via, { ...point52, route_type: "wire", width }]
            }
          });
        } finally {
          search.cancel();
        }
        yield;
      }
    }
  }
  return ends;
}
